import json
import re
import shutil
import subprocess
import tempfile
import unittest
from pathlib import Path

TARGET = Path(__file__).resolve().parent / "audio-visualizer.html"
MODEL_ID = "spectrum-model"

DRIVER = r"""
import * as M from './model.mjs';
const BANDS = M.BANDS, P = M.BEAT_PERIOD, LOOP = M.LOOP;
const PH = 12;
const times = [];
for (let k = 0; k < 8; k++) for (let j = 0; j < PH; j++) times.push((k + j / PH) * P);
const spec = times.map(t => Array.from(M.spectrum(t), Number));
const caps = times.map(t => Array.from(M.peaks(t), Number));
const loop = [0.13, 0.77, 1.41].map(t => [Array.from(M.spectrum(t), Number),
                                          Array.from(M.spectrum(t + LOOP), Number)]);
const wave = Array.from(M.waveform(0.31, 256), Number);
const pulse = times.map(t => Number(M.beat(t)));
console.log(JSON.stringify({ BANDS, P, LOOP, PH, times, spec, caps, loop, wave, pulse }));
"""


def node():
    return shutil.which("node") or shutil.which("node.exe")


def mean(xs):
    return sum(xs) / len(xs) if xs else 0.0


class Acceptance(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.raw = TARGET.read_text(encoding="utf-8")
        cls.model = cls.extract_model(cls.raw)
        cls.data = cls.run_model(cls.model) if cls.model and node() else None

    @staticmethod
    def extract_model(raw):
        m = re.search(r'<script[^>]*id=["\']%s["\'][^>]*>(.*?)</script>' % MODEL_ID,
                      raw, re.S | re.I)
        return m.group(1) if m else None

    @staticmethod
    def run_model(src):
        with tempfile.TemporaryDirectory() as tmp:
            d = Path(tmp)
            (d / "model.mjs").write_text(src, encoding="utf-8")
            (d / "driver.mjs").write_text(DRIVER, encoding="utf-8")
            done = subprocess.run([node(), str(d / "driver.mjs")], capture_output=True,
                                  text=True, timeout=60, cwd=d)
            if done.returncode != 0:
                raise AssertionError("model failed in node: %s" % done.stderr[-800:])
            return json.loads(done.stdout.strip().splitlines()[-1])

    def model_data(self):
        self.assertIsNotNone(self.model,
                             'no <script id="%s"> block found' % MODEL_ID)
        if not node():
            self.skipTest("node is not installed; cannot measure the model")
        self.assertIsNotNone(self.data, "model produced no data")
        return self.data

    def beat_slice(self, key, k):
        """The PH samples that span beat k, from its onset to just before the next."""
        data = self.model_data()
        ph = data["PH"]
        return data[key][k * ph:(k + 1) * ph]

    # --- the page itself -------------------------------------------------
    def test_is_one_self_contained_html_page(self):
        self.assertRegex(self.raw[:400].lower(), r"<!doctype html")
        self.assertIn("<canvas", self.raw.lower())

    def test_no_external_requests(self):
        for pat, why in ((r'src\s*=\s*["\'](https?:)?//', "external src"),
                         (r'href\s*=\s*["\'](https?:)?//', "external href"),
                         (r"@import", "css @import"),
                         (r'url\(\s*["\']?(https?:)?//', "external url()"),
                         (r"\bfetch\s*\(", "network fetch"),
                         (r"XMLHttpRequest", "XHR")):
            self.assertIsNone(re.search(pat, self.raw, re.I),
                              "page must be self-contained: found %s" % why)

    def test_signal_is_synthetic_not_captured(self):
        """No microphone, no audio file, no decoding: the mix is generated maths."""
        for pat, why in ((r"getUserMedia", "microphone capture"),
                         (r"mediaDevices", "media device access"),
                         (r"MediaStream", "media stream"),
                         (r"AudioContext", "web audio graph"),
                         (r"decodeAudioData", "audio file decoding"),
                         (r"createAnalyser", "live analyser node"),
                         (r"<audio\b", "<audio> element"),
                         (r"new\s+Audio\s*\(", "Audio() element")):
            self.assertIsNone(re.search(pat, self.raw, re.I),
                              "signal must be synthetic: found %s" % why)

    def test_animates_with_request_animation_frame(self):
        self.assertIn("requestAnimationFrame", self.raw)

    def test_model_is_separate_from_the_renderer(self):
        self.assertIsNotNone(self.model,
                             'the pure model must live in <script id="%s">' % MODEL_ID)
        for banned in ("getContext", "document.", "window.", "canvas"):
            self.assertNotIn(banned, self.model,
                             "model script must be pure math, found %r" % banned)

    def test_renderer_draws_every_model_output(self):
        """Bars, caps, ribbon and pulse all have to reach the canvas."""
        rest = re.sub(r'<script[^>]*id=["\']%s["\'][^>]*>.*?</script>' % MODEL_ID,
                      "", self.raw, flags=re.S | re.I)
        for name in ("spectrum(", "peaks(", "waveform(", "beat("):
            self.assertIn(name, rest,
                          "renderer never calls %s from the model" % name)

    # --- the model, measured --------------------------------------------
    def test_band_count_and_range(self):
        data = self.model_data()
        bands = data["BANDS"]
        self.assertTrue(24 <= bands <= 256,
                        "band count %s outside a plausible 24-256" % bands)
        for row in data["spec"]:
            self.assertEqual(len(row), bands, "spectrum length must equal BANDS")
            for v in row:
                self.assertEqual(v, v, "NaN in spectrum")
                self.assertGreaterEqual(v, 0.0, "magnitude below 0")
                self.assertLessEqual(v, 1.0, "magnitude above 1")

    def test_bass_is_louder_than_treble(self):
        data = self.model_data()
        q = data["BANDS"] // 4
        low = mean([mean(row[:q]) for row in data["spec"]])
        high = mean([mean(row[-q:]) for row in data["spec"]])
        self.assertGreater(high, 0.0, "treble bands are entirely silent")
        self.assertGreater(low, 1.5 * high,
                           "bass must dominate treble: %.4f vs %.4f" % (low, high))

    def test_beat_lands_on_the_stated_period(self):
        data = self.model_data()
        period, ph = data["P"], data["PH"]
        self.assertTrue(0.25 <= period <= 2.0,
                        "BEAT_PERIOD %s is not a musical period" % period)
        for k in range(8):
            onset = sum(self.beat_slice("spec", k)[0])
            tail = sum(self.beat_slice("spec", k)[ph - 1])
            self.assertGreater(onset, 1.4 * tail,
                               "beat %d does not pulse: onset %.3f vs tail %.3f"
                               % (k, onset, tail))
            self.assertGreater(data["pulse"][k * ph], 0.5,
                               "beat() must fire at the onset of beat %d" % k)

    def test_loop_repeats_exactly(self):
        data = self.model_data()
        loop, period = data["LOOP"], data["P"]
        self.assertAlmostEqual(loop / period, round(loop / period), delta=1e-9,
                               msg="LOOP must be a whole number of beats")
        for a, b in data["loop"]:
            for i, (x, y) in enumerate(zip(a, b)):
                self.assertAlmostEqual(x, y, delta=1e-9,
                                       msg="band %d is not periodic over LOOP" % i)

    def test_peak_caps_decay_monotonically_between_beats(self):
        data = self.model_data()
        ph = data["PH"]
        for k in range(8):
            rows = self.beat_slice("caps", k)
            for j in range(1, ph):
                for i, (prev, cur) in enumerate(zip(rows[j - 1], rows[j])):
                    self.assertLessEqual(cur, prev + 1e-9,
                                         "cap %d rose inside beat %d: %.6f -> %.6f"
                                         % (i, k, prev, cur))
            self.assertLess(sum(rows[ph - 1]), 0.95 * sum(rows[0]),
                            "caps barely fall during beat %d" % k)

    def test_peak_caps_never_sit_below_their_bars(self):
        data = self.model_data()
        for n, (cap_row, spec_row) in enumerate(zip(data["caps"], data["spec"])):
            for i, (cap, mag) in enumerate(zip(cap_row, spec_row)):
                self.assertGreaterEqual(cap, mag - 1e-9,
                                        "cap %d below its bar at sample %d: %.6f < %.6f"
                                        % (i, n, cap, mag))

    def test_waveform_is_a_usable_ribbon(self):
        wave = self.model_data()["wave"]
        self.assertEqual(len(wave), 256, "waveform(t, n) must return n samples")
        for v in wave:
            self.assertEqual(v, v, "NaN in waveform")
            self.assertLessEqual(abs(v), 1.0 + 1e-9, "waveform outside -1..1")
        self.assertGreater(max(wave) - min(wave), 0.2,
                           "waveform is flat: nothing to draw")


if __name__ == "__main__":
    unittest.main()
